import assert from 'node:assert/strict';
import {writeFile} from 'node:fs/promises';
import {join} from 'node:path';
export async function checkSectionCollapse({send,evaluate,until,click,viewport,output}) {
 const key='relics.ui.sections.v1',url='http://127.0.0.1:1420/?rhythmFixture=mixed';
 const screenshots=[];
 async function press(key,code,n){for(const type of ['keyDown','keyUp'])await send('Input.dispatchKeyEvent',{type,key,code,windowsVirtualKeyCode:n,...(key==='Enter'&&type==='keyDown'?{text:'\r',unmodifiedText:'\r'}:{})});}
 async function state(i,r,description){await until('document.querySelector("#inventory-toggle")?.getAttribute("aria-expanded")==='+JSON.stringify(String(i))+'&&document.querySelector("#rhythm-toggle")?.getAttribute("aria-expanded")==='+JSON.stringify(String(r))+'&&document.querySelector("#inventory-body").hidden==='+String(!i)+'&&document.querySelector("#rhythm-body").hidden==='+String(!r),description);}
 async function loaded(){await until('document.querySelectorAll(".relic-item").length===6','Synthetic fixture available for disclosure checks');}
 async function chart(description){await until('(()=>{const h=document.querySelector(".rhythm-plot"),c=h?.querySelector("canvas");if(!c)return false;const b=c.getBoundingClientRect();if(b.width<200||b.right>innerWidth+1||Math.abs(b.width-h.clientWidth)>2)return false;return [...c.getContext("2d").getImageData(0,0,c.width,c.height).data].some((v,i)=>i%4===3&&v>0);})()',description);}
 async function capture(name){await evaluate('window.scrollTo(0,0)');await evaluate('new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))');const size=await evaluate('({width:innerWidth,height:Math.ceil(document.documentElement.scrollHeight)})');const img=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true,clip:{x:0,y:0,...size,scale:1}});await writeFile(join(output,name),Buffer.from(img.data,'base64'));screenshots.push(name);}
 async function storageState(i,r){await until('(()=>{const p=JSON.parse(localStorage.getItem('+JSON.stringify(key)+'));return p.version===1&&p.inventoryExpanded==='+i+'&&p.rhythmExpanded==='+r+'&&Object.keys(p).length===3;})()','Only the two expansion preferences persist');}
 await viewport(1440,1000);await evaluate('localStorage.removeItem('+JSON.stringify(key)+')');await send('Page.navigate',{url});await loaded();await state(true,true,'Fresh profile defaults both sections expanded');await chart('Expanded default chart has real pixels and correct width');await capture('collapse-both-expanded.png');
 await click('.date-shortcuts button:nth-child(2)');const day=await evaluate('document.querySelector("input[type=date]").value');
 await click('#inventory-toggle');await state(false,true,'Inventory collapses independently');
 assert.ok(await evaluate('document.querySelector(".inventory-heading").textContent.includes("Активных привычек: 6")'));assert.equal(await evaluate('document.querySelectorAll(".relic-item").length'),6);
 const ax=await send('Accessibility.getFullAXTree');assert.ok(!ax.nodes.some(n=>n.role?.value==='button'&&n.name?.value?.startsWith('Отметить:')));assert.ok(ax.nodes.some(n=>n.role?.value==='button'&&n.name?.value?.includes('Добавить привычку')));assert.ok(ax.nodes.some(n=>n.role?.value==='button'&&n.name?.value==='Архив привычек'));
 await capture('collapse-inventory.png');await click('#rhythm-toggle');await state(false,false,'Both sections can remain collapsed');await until('!document.querySelector(".rhythm-plot canvas")','Collapsed chart releases drawing resources');await storageState(false,false);await capture('collapse-both.png');
 const hiddenAx=await send('Accessibility.getFullAXTree');assert.ok(!hiddenAx.nodes.some(n=>n.role?.value==='combobox'&&n.name?.value==='Период графика'));assert.ok(!hiddenAx.nodes.some(n=>n.role?.value==='table'));assert.ok(await evaluate('document.querySelector("#inventory-body").inert&&document.querySelector("#rhythm-body").inert'));
 // Creation and existing archive access stay usable outside the hidden inventory body.
 await click('.inventory-heading .button-primary');await until('!!document.querySelector(".creation-form")','Add Habit opens even while inventory is collapsed');await evaluate('document.querySelector("#habit-name").focus()');await send('Input.insertText',{text:'Проверка свёрнутого раздела'});if(!await evaluate('document.querySelector("#sphere-mind").checked'))await click('#sphere-mind');await evaluate('document.querySelector("#habit-frequency").value="weekly";document.querySelector("#habit-frequency").dispatchEvent(new Event("change",{bubbles:true}))');await click('.creation-form button[type=submit]');await until('!document.querySelector(".creation-form")&&document.querySelectorAll(".relic-item").length===7','Collapsed inventory accepts a created synthetic habit without unmounting data');await state(false,false,'Saving a habit does not change disclosure preferences');assert.ok(await evaluate('document.querySelector(".inventory-heading").textContent.includes("Активных привычек: 7")'));
 await click('.inventory-heading .button-quiet');await until('document.querySelector("#habits-title").textContent==="Архив реликвий"','Archive view stays reachable from collapsed inventory');await state(false,false,'Archive access retains independent collapsed state');await click('.inventory-heading .button-quiet');
 // Navigation plus offline navigation preserve preferences and selected logging date.
 await click('.app-rail [data-nav=chronicle]');await until('!!document.querySelector("#chronicle")','Chronicle remains a genuine navigation destination');await click('.app-rail [data-nav=sanctuary]');await state(false,false,'Collapse preferences survive Chronicle navigation');assert.equal(await evaluate('document.querySelector("input[type=date]").value'),day);
 await send('Network.enable');await send('Network.emulateNetworkConditions',{offline:true,latency:0,downloadThroughput:0,uploadThroughput:0});try{await click('.app-rail [data-nav=chronicle]');await click('.app-rail [data-nav=sanctuary]');await state(false,false,'Offline navigation keeps both preferences');}finally{await send('Network.emulateNetworkConditions',{offline:false,latency:0,downloadThroughput:-1,uploadThroughput:-1});}
 // Full document restart reads storage; it intentionally does not persist unrelated analytics settings.
 await send('Page.reload');await loaded();await state(false,false,'Two preferences survive full browser application reload');await click('#inventory-toggle');await state(true,false,'Inventory can be expanded while analytics stays collapsed');await capture('collapse-rhythm.png');
 await click('#rhythm-toggle');await state(true,true,'Both can be reopened after persisted collapse');await chart('Chart recreates at correct width after reload and expansion');
 // Focus inside content must be rescued even when collapse is requested programmatically.
 await evaluate('document.querySelector(".completion-button:not(:disabled)").focus();document.querySelector("#inventory-toggle").click()');await state(false,true,'Inventory body hides when toggled from an internal focus');await until('document.activeElement.id==="inventory-toggle"','Focus leaves newly hidden inventory for its toggle');await press(' ','Space',32);await state(true,true,'Space expands inventory with native button semantics');await press('Enter','Enter',13);await state(false,true,'Enter collapses inventory');await press('Enter','Enter',13);await state(true,true,'Enter restores inventory without logging');
 for(const [keyName,keyCode,n,value] of [['Home','Home',36,'1'],['ArrowDown','ArrowDown',40,'4'],['End','End',35,'8']]){
  await evaluate('document.querySelector(".rhythm-period select").focus()');await press(keyName,keyCode,n);await until('document.querySelector(".rhythm-period select").value==='+JSON.stringify(value),'Real period control selects '+value+' weeks');
  if(await evaluate('document.querySelector("[data-mode=shares]").getAttribute("aria-pressed")!=="true"'))await click('[data-mode=shares]');if(await evaluate('document.querySelector(".rhythm-legend [data-sphere=work] input").checked'))await click('.rhythm-legend [data-sphere=work] input');
  await evaluate('document.querySelector(".rhythm-table").open=true;document.querySelector(".rhythm-period select").focus();document.querySelector("#rhythm-toggle").click()');await state(true,false,'Analytics '+value+'-week collapse is independent');await until('document.activeElement.id==="rhythm-toggle"','Analytics collapse safely returns internal focus');await press(' ','Space',32);await state(true,true,'Space restores analytics '+value+'-week view');
  assert.equal(await evaluate('document.querySelector(".rhythm-period select").value'),value);assert.equal(await evaluate('document.querySelector("[data-mode=shares]").getAttribute("aria-pressed")'),'true');assert.equal(await evaluate('document.querySelector(".rhythm-legend [data-sphere=work] input").checked'),false);assert.equal(await evaluate('document.querySelector(".rhythm-table").open'),true);if(value!=='1')await chart('Correct real chart rendering after '+value+'-week expansion');
 }
 await chart('Eight-week configured chart remains nonblank');
 for(const [width,height] of [[1920,1080],[1280,800],[390,844],[320,844]]){await click('#rhythm-toggle');await viewport(width,height);await click('#rhythm-toggle');await state(true,true,'Disclosure reopens after resize to '+width);await until('document.documentElement.scrollWidth<=innerWidth','Disclosure layout has no horizontal overflow at '+width);await chart('Chart width and pixels are correct after hidden resize to '+width);if(width===390)await capture('collapse-narrow-windows.png');}
 await viewport(1440,1000);
 await click('#inventory-toggle');await click('#rhythm-toggle');await storageState(false,false);await send('Page.reload');await loaded();await state(false,false,'Restart restores only the two section preferences');await click('#rhythm-toggle');assert.equal(await evaluate('document.querySelector(".rhythm-period select").value'),'4');assert.equal(await evaluate('document.querySelector("[data-mode=units]").getAttribute("aria-pressed")'),'true');assert.ok(await evaluate('[...document.querySelectorAll(".rhythm-legend input")].every(i=>i.checked)'));
 // Corrupt/unsupported records and storage getter or write failures are isolated test-only browser overrides.
 for(const value of ['{bad json',JSON.stringify({version:2,inventoryExpanded:false,rhythmExpanded:false})]){await evaluate('localStorage.setItem('+JSON.stringify(key)+','+JSON.stringify(value)+')');await send('Page.reload');await loaded();await state(true,true,'Invalid stored preference record falls back to both expanded');}
 for(const source of ["Object.defineProperty(window,'localStorage',{get(){throw new DOMException('Synthetic denial','SecurityError')}})","Storage.prototype.setItem=function(){throw new DOMException('Synthetic full storage','QuotaExceededError')}" ]){
  await evaluate('localStorage.removeItem('+JSON.stringify(key)+')');const init=await send('Page.addScriptToEvaluateOnNewDocument',{source});try{await send('Page.reload');await loaded();await state(true,true,'Unavailable storage falls back without blocking app');await click('#inventory-toggle');await state(false,true,'Session controls still work when storage is denied');}finally{await send('Page.removeScriptToEvaluateOnNewDocument',{identifier:init.identifier});await send('Page.navigate',{url});await loaded();}
 }
 await evaluate('localStorage.removeItem('+JSON.stringify(key)+')');await send('Page.reload');await loaded();await state(true,true,'Synthetic disclosure verification restores fresh expanded preferences');await send('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});assert.equal(await evaluate('getComputedStyle(document.querySelector(".section-toggle span")).transitionDuration'),'0s');await send('Emulation.setEmulatedMedia',{features:[]});
 await writeFile(join(output,'section-collapse-proof.json'),JSON.stringify({source:'Actual browser controls and synthetic in-memory journal',key,onlyTwoExpansionPreferences:true,defaultBothExpanded:true,allFourStates:true,browserReloadPersistence:true,offlineNavigation:true,nativeOfflineRestartVerified:false,nativeOwnerAcceptancePending:true,screenshots},null,2));
 await evaluate('localStorage.removeItem('+JSON.stringify(key)+')');await send('Page.navigate',{url:'http://127.0.0.1:1420'});await loaded();
}
